<?php namespace App\Policies; use App\Models\User; use App\Models\AiInsight; class AiInsightPolicy { public function view(User $user, AiInsight $insight) { if ($user->hasRole(["admin", "hr"])) return true; if ($user->employee && $user->employee->id === $insight->employee_id) return true; if ($user->hasRole("dept_head") && $user->employee && $user->employee->department_id === $insight->department_id) return true; return false; } }